/* Chia CHI TIẾT bài A0, A1 (17/10, theo chủ dự án): mỗi phần một điểm ngữ pháp nhỏ,
 * khoảng 8 câu luyện. Ghi đè cách chia phần cũ (cauTruc.js + boSungA0A1.js).
 *   khoi: số = chỉ số khối trong bai.phan (dùng lại bảng cũ), hoặc khối mới.
 *   cau : số = chỉ số câu trong bai.baiTap (giữ câu cũ, giữ lịch ôn), hoặc câu mới.
 * « Ôn tập cả bài » vẫn dùng bai.baiTap. Nội dung học: KHÔNG dùng dấu gạch dài. */

const q = (de, pa, dap, giai) => ({ loai: "qcm", de, pa, dap, giai });
const d = (de, dap, giai) => ({ loai: "dien", de, dap: [].concat(dap), giai });
const vf = (de, dung, giai) => ({ loai: "vf", de, dung, giai });
const sap = (goiY, cau, giai) => ({ loai: "sap", de: goiY, goiY, dap: [cau], giai });
const sua = (sai, dung, giai) => ({ loai: "sua", de: sai, dap: [].concat(dung), giai });
const bang = (tieuDe, cot, hang) => ({ loai: "bang", tieuDe, cot, hang });
const vidu = (...ds) => ({ loai: "vidu", ds });

